head.b:skin:
/* VoxLab theme — colours from the VoxLab logo: dark navy + cyan-blue-purple */
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#05081f;color:#eef1ff}
a{color:#00d4ff;text-decoration:none}
.wrap{max-width:1040px;margin:0 auto;padding:0 20px}
header.top{padding:22px 0;border-bottom:1px solid #1b2450}
.logo{font-size:32px;font-weight:800;letter-spacing:.5px;background:linear-gradient(90deg,#00d4ff,#4868D8,#8b5cf6);-webkit-background-clip:text;background-clip:text;color:transparent}
.nav{float:right;padding-top:8px}
.nav a{margin-left:18px;color:#c7d0ff}
.hero{padding:72px 0 48px;text-align:center}
.hero h1{font-size:52px;line-height:1.05;margin:12px 0}
.grad{background:linear-gradient(90deg,#00d4ff,#4868D8,#8b5cf6);-webkit-background-clip:text;background-clip:text;color:transparent}
.hero p{font-size:19px;color:#c7d0ff;max-width:720px;margin:0 auto}
.btn{display:inline-block;margin-top:24px;padding:14px 26px;border-radius:999px;background:linear-gradient(90deg,#00d4ff,#4868D8,#8b5cf6);color:#fff;font-weight:700}
.btn2{display:inline-block;margin-top:24px;margin-left:12px;padding:14px 26px;border-radius:999px;border:1px solid #2a3a7a;color:#fff}
.sec{padding:56px 0;border-top:1px solid #1b2450}
.sec h2{font-size:34px;margin:0 0 10px}
.sec p.lead{color:#c7d0ff;font-size:18px;max-width:760px}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:26px}
.card{background:#0d1433;border:1px solid #2a3a7a;border-radius:16px;padding:22px}
.card h3{margin:0 0 8px}
.card p{color:#c7d0ff;margin:0}
.tag{display:inline-block;font-size:12px;font-weight:700;letter-spacing:.5px;padding:4px 10px;border-radius:999px;background:#1b2450;color:#00d4ff;margin-bottom:10px}
.tag.soon{background:#3a2a5a;color:#d8b4fe}
table{width:100%;border-collapse:collapse;margin-top:22px}
th,td{text-align:left;padding:12px;border-bottom:1px solid #1b2450;color:#eef1ff}
td.m{color:#c7d0ff}
ol.steps{font-size:18px;line-height:1.9;color:#eef1ff}
footer{padding:36px 0;border-top:1px solid #1b2450;color:#9aa6d8;text-align:center}
@media(max-width:760px){.hero h1{font-size:36px}.grid{grid-template-columns:1fr}.nav{display:none}}

.logoimg{height:52px;width:52px;border-radius:14px;vertical-align:middle;margin-right:12px;box-shadow:0 0 24px rgba(0,212,255,.45)}
.grad{background:linear-gradient(90deg,#00d4ff,#4868D8,#8b5cf6,#00d4ff);background-size:200% auto;-webkit-background-clip:text;background-clip:text;color:transparent;animation:gradShift 6s linear infinite}
@keyframes gradShift{to{background-position:200% center}}
.hero{animation:fadeUp 1s ease both}
@keyframes fadeUp{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:translateY(0)}}
.wave{display:flex;gap:5px;justify-content:center;align-items:flex-end;height:42px;margin:22px 0 0}
.wave span{width:6px;border-radius:3px;background:linear-gradient(180deg,#00d4ff,#8b5cf6);animation:waveBounce 1.2s ease-in-out infinite}
.wave span:nth-child(1){height:14px;animation-delay:0s}.wave span:nth-child(2){height:28px;animation-delay:.1s}.wave span:nth-child(3){height:40px;animation-delay:.2s}.wave span:nth-child(4){height:24px;animation-delay:.3s}.wave span:nth-child(5){height:36px;animation-delay:.15s}.wave span:nth-child(6){height:18px;animation-delay:.25s}.wave span:nth-child(7){height:32px;animation-delay:.05s}
@keyframes waveBounce{0%,100%{transform:scaleY(.4)}50%{transform:scaleY(1)}}
.card{transition:transform .3s ease,box-shadow .3s ease}
.oslogo{height:40px;width:40px;flex-shrink:0;margin-top:4px;filter:grayscale(1);opacity:.85}

.card:hover{transform:translateY(-6px);box-shadow:0 18px 40px rgba(0,212,255,.18)}
.btn{transition:transform .2s ease,box-shadow .2s ease}
.btn:hover{transform:scale(1.04);box-shadow:0 0 28px rgba(72,104,216,.6)}
.sec{animation:fadeUp .8s ease both}
